"""QUEUE.md (one row per work unit, status column carried over) and CENSUS.md (evidence) from a census dict."""

from __future__ import annotations

import json
import re
from collections import defaultdict
from pathlib import Path

SLICE = {
    "SCALAR_MEMBER": "B", "STRUCT_ALIAS": "B", "MISTYPED": "B", "STRUCT": "C", "ARRAY": "C", "F32_TABLE": "C",
    "SUBWORD": "C", "STRING": "C", "LITERAL_POOL": "L", "LITERAL": "L",
}  # fmt: skip
HEADER = [
    "# DATA-TYPES work queue (generated by `decomp data census --queue`; edit only the status column)", "",
    "Slices: A = TOOL, B = declared owners + mistyped, C = new aggregates/strings, L = literal pools (land with their fn).",
    "Rows marked DONE/LANDED/CLAIMED/BLOCKED/NOCHANGE by hand are carried over by base symbol on regeneration.", "",
    "| id | prio | class | base | members | owner/decl | evidence | open consumers | slice | status |",
    "|---|---|---|---|---|---|---|---|---|---|",
]  # fmt: skip


def parse_probe_log(text: str) -> dict[str, list[str]]:
    """probe log lines -> sym -> ['fn a->b'], and 'literals:FN' -> [...]."""
    wins: dict[str, list[str]] = defaultdict(list)
    for line in text.splitlines():
        m = re.match(r"(\w+) base=\d+ final=\d+ kept=\[(.*)\]", line)
        if not m:
            continue
        for k in m.group(2).split("; "):
            w = re.match(r"(\w+):instruct (\d+)->(\d+)", k)
            if w:
                wins[w.group(1)].append(f"{m.group(1)} {w.group(2)}->{w.group(3)}")
            w = re.match(r"literals\((\d+)\) (\d+)->(\d+)", k)
            if w:
                wins["literals:" + m.group(1)].append(f"{m.group(1)} {w.group(2)}->{w.group(3)}")
    return wins


def queue_rows(clusters: list, lones: list, open_fns: set[str]) -> list:
    rows = []
    for c in clusters:
        if c["class"] in ("SCALAR_MEMBER", "STRUCT_ALIAS"):
            groups = defaultdict(list)
            for m in c["members"][1:]:
                groups[m["inner"].split("+")[0] or c["base"]].append(m)
            for sub, ms in groups.items():
                cls = (
                    "SCALAR_MEMBER"
                    if any((set(m["decl_kind"]) & {"i", "f", "p"}) or (not m["decl"] and m["access"]) for m in ms)
                    else "STRUCT_ALIAS"
                )
                oc = sorted({f for m in ms for f in m["consumers"] if f in open_fns})
                ev = "INSIDE" + (
                    " UNSTABLE" if any(not m["owner_stable"] or not m["sizeof_stable"] for m in ms) else ""
                )
                rows.append((("P1" if oc and cls == "SCALAR_MEMBER" else "P2" if cls == "SCALAR_MEMBER" else "P3"), cls, sub, ms,
                             f"owner {sub} (in {c['base']})", ev, oc))  # fmt: skip
        else:
            rows.append((c["prio"], c["class"], c["base"], c["members"], "new type" if c["class"] != "LITERAL_POOL" else "fn literals",
                         ",".join(c["kinds"]), c.get("open_consumers", [])))  # fmt: skip
    litfn = defaultdict(list)  # open fn -> its TU-local literal pool symbols: one L row per fn
    for x in lones:
        if x["class"] == "LITERAL":
            for f in sorted(set(x["consumers"]) & open_fns)[:1]:
                litfn[f].append(x)
    for f, xs in litfn.items():
        rows.append(("P9", "LITERAL", f, xs, f"fn literal pool ({len(xs)})", "literal", [f]))
    for x in lones:
        if x["class"] in ("MISTYPED", "STRING"):
            oc = sorted(set(x["consumers"]) & open_fns)
            rows.append(("P1" if oc else "P2", x["class"], x["sym"], [x], "decl %s" % "/".join(x["decl"])[:60],
                         "decl-vs-access" if x["class"] == "MISTYPED" else "string", oc))  # fmt: skip
    rows.sort(key=lambda r: (r[0], -len(r[6]), -len(r[3])))
    return rows


def carried_status(queue: Path | None) -> dict[str, str]:
    prev: dict[str, str] = {}
    if queue and queue.is_file():
        for line in queue.read_text().splitlines():
            p = [x.strip() for x in line.split("|")]
            if len(p) > 10 and p[1].startswith("Q"):
                prev[p[4]] = p[10]
    return prev


def render_queue(data: dict, open_fns: set[str], wins: dict, prev: dict[str, str]) -> str:
    md = list(HEADER)
    for i, (prio, cls, base, ms, own, ev, oc) in enumerate(queue_rows(data["clusters"], data["lones"], open_fns), 1):
        w = [x for m in ms for x in wins.get(m["sym"], [])]
        if cls in ("LITERAL_POOL", "LITERAL"):
            w = [x for f in oc for x in wins.get("literals:" + f, [])]
        if w:
            ev = ev + " probe:" + ",".join(sorted(set(w))[:3])
            if prio == "P2":
                prio = "P1"
        mem = ",".join(m["sym"] for m in ms[:6]) + (" +%d" % (len(ms) - 6) if len(ms) > 6 else "")
        md.append("| Q%03d | %s | %s | %s | %s | %s | %s | %s | %s | %s |" % (
            i, prio, cls, base, mem, own.replace("|", "/"), ev, ",".join(oc[:4]) + ("..." if len(oc) > 4 else ""),
            SLICE.get(cls, "C"), prev.get(base, "-"))
        )  # fmt: skip
    return "\n".join(md) + "\n"


def render_census(data: dict, stats: dict, open_fns: set[str], fnscore: dict, ref_acc_fns) -> str:
    clusters, lones = data["clusters"], data["lones"]

    def fnmark(fn: str) -> str:
        if fn in open_fns:
            return fn + "(OPEN)"
        s = fnscore.get(fn)
        return fn if s is None or s >= 100 else "%s(%.0f)" % (fn, s)

    sym2c = {m["sym"]: c for c in clusters for m in c["members"]}
    sym2l = {x["sym"]: x for x in lones}
    md = ["# DATA-TYPES census (generated by `decomp data census`; reference-version addresses)", "", "stats: `" + json.dumps(stats) + "`", "",
          "## Open fns -> raw globals", "Cell: SYM[class:cluster base] ; no tag = lone, correctly typed.", ""]  # fmt: skip
    for fn in sorted(open_fns):
        ss = ref_acc_fns.get(fn, [])
        if not ss:
            continue
        cells = []
        for n in ss:
            if n in sym2c:
                cells.append("%s[%s:%s]" % (n, sym2c[n]["class"], sym2c[n]["base"]))
            elif n in sym2l and sym2l[n]["class"] != "LONE":
                cells.append("%s[%s]" % (n, sym2l[n]["class"]))
            else:
                cells.append(n)
        md.append("- %s: %s" % (fn, ", ".join(cells)))
    md += ["", "## Clusters (prio order)", ""]
    for c in clusters:
        if c["prio"] == "P9":
            continue
        cons = sorted({fn for m in c["members"] for fn in m["consumers"]})
        md.append("### %s %s %s (%d members; evidence %s%s)" % (c["prio"], c["base"], c["class"], len(c["members"]), ",".join(c["kinds"]),
                                                              "; UNSTABLE " + ",".join(c["unstable"]) if c["unstable"] else ""))  # fmt: skip
        b0 = int(c["members"][0]["addr"], 16)
        for m in c["members"]:
            md.append("  - %s +0x%X size %d sizeof %s acc %s decl %s %s%s%s" % (
                m["sym"], int(m["addr"], 16) - b0, m["size"], m["sizeof"] or "-", list(m["access"])[:3], m["decl"] or "-",
                ("owner " + m["owner"]) if m["owner"] else "", (" path " + m["path"]) if m.get("path") else "",
                (" init " + m["init"]) if m["init"] else "")
            )  # fmt: skip
        for e in c["edges"][:4]:
            md.append("  - edge %s->%s d=0x%X stable=%s %s" % (e["from"], e["to"], e["delta"], e["stable"], e["ev"]))
        md.append(
            "  - consumers(%d): %s"
            % (len(cons), ", ".join(fnmark(f) for f in cons[:20]) + (" ..." if len(cons) > 20 else ""))
        )
    md += ["", "## Mistyped lone globals", ""]
    for x in lones:
        if x["class"] == "MISTYPED":
            md.append(
                "- %s @%s acc %s decl %s files %d"
                % (x["sym"], x["addr"], list(x["access"])[:3], x["decl"], len(x["decl_files"]))
            )
    return "\n".join(md) + "\n"
